begin;
create extension if not exists pgcrypto;
create type public.user_role as enum ('personal','student','teacher','admin');
create type public.material_status as enum ('draft','published','archived');
create type public.version_status as enum ('draft','published');
create type public.submission_status as enum ('draft','submitted','returned');

create table public.profiles(id uuid primary key references auth.users on delete cascade,role public.user_role not null default 'personal',display_name text,grade_band text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.materials(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,title text not null,status public.material_status not null default 'draft',current_version_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.material_versions(id uuid primary key default gen_random_uuid(),material_id uuid not null references public.materials on delete cascade,version_number integer not null check(version_number>0),document_json jsonb not null,status public.version_status not null default 'draft',created_by uuid not null references public.profiles,created_at timestamptz not null default now(),published_at timestamptz,unique(material_id,version_number));
alter table public.materials add constraint materials_current_version_fk foreign key(current_version_id) references public.material_versions;
create table public.material_assets(id uuid primary key default gen_random_uuid(),material_version_id uuid not null references public.material_versions on delete restrict,owner_id uuid not null references public.profiles,asset_type text not null check(asset_type in ('background','worksheet','drawing')),storage_path text not null unique,mime_type text not null check(mime_type in ('image/png','image/jpeg','image/webp')),width integer not null check(width between 512 and 8192),height integer not null check(height between 512 and 8192),alt_text text not null check(length(trim(alt_text))>0),created_at timestamptz not null default now());
create table public.material_reviews(material_version_id uuid primary key references public.material_versions on delete cascade,reviewer_id uuid not null references public.profiles,content_matches boolean not null default false,numbers_match boolean not null default false,answers_match boolean not null default false,readable boolean not null default false,answer_areas_valid boolean not null default false,rights_confirmed boolean not null default false,reviewed_at timestamptz not null default now());
create table public.classrooms(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles,name text not null,join_code text not null unique check(join_code ~ '^[A-Z0-9]{8,10}$'),created_at timestamptz not null default now());
create table public.classroom_members(classroom_id uuid not null references public.classrooms on delete cascade,student_id uuid not null references public.profiles on delete cascade,joined_at timestamptz not null default now(),primary key(classroom_id,student_id));
create table public.assignments(id uuid primary key default gen_random_uuid(),classroom_id uuid not null references public.classrooms on delete cascade,material_version_id uuid not null references public.material_versions on delete restrict,title text not null,instructions text,due_at timestamptz,published_at timestamptz,created_by uuid not null references public.profiles,created_at timestamptz not null default now());
create table public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments on delete restrict,student_id uuid not null references public.profiles,status public.submission_status not null default 'draft',submitted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,student_id));
create table public.submission_answers(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions on delete cascade,question_id text not null,answer_text text,answer_json jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(submission_id,question_id));
create table public.submission_feedback(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions on delete cascade,source text not null check(source in ('ai','teacher','system')),feedback_text text not null,score numeric,created_at timestamptz not null default now());
create table public.teacher_comments(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions on delete cascade,teacher_id uuid not null references public.profiles,comment_text text not null,created_at timestamptz not null default now());
create table public.external_material_drafts(id uuid primary key default gen_random_uuid(),source text not null,request_summary text not null,manifest_json jsonb not null,status text not null default 'draft' check(status in ('draft','claimed','expired')),claimed_by uuid references public.profiles,claimed_at timestamptz,created_at timestamptz not null default now(),expires_at timestamptz not null);
create table public.external_action_requests(id uuid primary key default gen_random_uuid(),idempotency_key text not null unique,operation text not null,request_hash text,response_json jsonb not null,created_at timestamptz not null default now());
create table public.claim_tokens(id uuid primary key default gen_random_uuid(),draft_id uuid not null references public.external_material_drafts on delete cascade,token_hash text not null unique,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());

create function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,role,display_name) values(new.id,'personal',new.raw_user_meta_data->>'display_name');return new;end$$;
create trigger auth_user_profile after insert on auth.users for each row execute function public.new_profile();
create function public.prevent_role_change() returns trigger language plpgsql as $$begin if old.role<>new.role and coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'role cannot be changed';end if;return new;end$$;
create trigger profiles_role_guard before update on public.profiles for each row execute function public.prevent_role_change();
create function public.freeze_published_version() returns trigger language plpgsql as $$begin if old.status='published' then raise exception 'published versions are immutable';end if;return new;end$$;
create trigger material_version_immutable before update or delete on public.material_versions for each row execute function public.freeze_published_version();
create function public.guard_submitted_answer() returns trigger language plpgsql as $$begin if exists(select 1 from public.submissions s where s.id=coalesce(new.submission_id,old.submission_id) and s.status='submitted') then raise exception 'submitted answers are immutable';end if;return coalesce(new,old);end$$;
create trigger submitted_answer_guard before update or delete on public.submission_answers for each row execute function public.guard_submitted_answer();

create function public.create_external_material_draft(p_draft_id uuid,p_source text,p_summary text,p_manifest jsonb,p_expires_at timestamptz,p_token_hash text,p_idempotency_key text,p_response jsonb) returns void language plpgsql security definer set search_path='' as $$begin insert into public.external_material_drafts(id,source,request_summary,manifest_json,expires_at) values(p_draft_id,p_source,p_summary,p_manifest,p_expires_at);insert into public.claim_tokens(draft_id,token_hash,expires_at) values(p_draft_id,p_token_hash,p_expires_at);insert into public.external_action_requests(idempotency_key,operation,response_json) values(p_idempotency_key,'createMaterialDraft',p_response);end$$;
revoke all on function public.create_external_material_draft from public,anon,authenticated;
create function public.claim_external_material(p_token_hash text) returns uuid language plpgsql security definer set search_path='' as $$declare t public.claim_tokens;d public.external_material_drafts;m uuid;v uuid;begin select * into t from public.claim_tokens where token_hash=p_token_hash and used_at is null and expires_at>now() for update;if not found then raise exception 'invalid claim';end if;select * into d from public.external_material_drafts where id=t.draft_id and claimed_by is null for update;if not found then raise exception 'invalid claim';insert into public.materials(owner_id,title) values(auth.uid(),d.manifest_json->'metadata'->>'title') returning id into m;insert into public.material_versions(material_id,version_number,document_json,created_by) values(m,1,d.manifest_json,auth.uid()) returning id into v;update public.external_material_drafts set status='claimed',claimed_by=auth.uid(),claimed_at=now() where id=d.id;update public.claim_tokens set used_at=now() where id=t.id;return m;end$$;
grant execute on function public.claim_external_material(text) to authenticated;

alter table public.profiles enable row level security;alter table public.materials enable row level security;alter table public.material_versions enable row level security;alter table public.material_assets enable row level security;alter table public.material_reviews enable row level security;alter table public.classrooms enable row level security;alter table public.classroom_members enable row level security;alter table public.assignments enable row level security;alter table public.submissions enable row level security;alter table public.submission_answers enable row level security;alter table public.submission_feedback enable row level security;alter table public.teacher_comments enable row level security;alter table public.external_material_drafts enable row level security;alter table public.external_action_requests enable row level security;alter table public.claim_tokens enable row level security;
create policy profile_self_read on public.profiles for select using(id=auth.uid() or exists(select 1 from public.classroom_members cm join public.classrooms c on c.id=cm.classroom_id where cm.student_id=profiles.id and c.teacher_id=auth.uid()));
create policy profile_self_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy materials_owner_all on public.materials for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy materials_assigned_read on public.materials for select using(exists(select 1 from public.material_versions mv join public.assignments a on a.material_version_id=mv.id join public.classroom_members cm on cm.classroom_id=a.classroom_id where mv.material_id=materials.id and cm.student_id=auth.uid() and a.published_at is not null));
create policy versions_owner_all on public.material_versions for all using(exists(select 1 from public.materials m where m.id=material_id and m.owner_id=auth.uid())) with check(status='draft' and exists(select 1 from public.materials m where m.id=material_id and m.owner_id=auth.uid()));
create policy versions_assigned_read on public.material_versions for select using(exists(select 1 from public.assignments a join public.classroom_members cm on cm.classroom_id=a.classroom_id where a.material_version_id=id and cm.student_id=auth.uid() and a.published_at is not null));
create policy assets_owner_all on public.material_assets for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy reviews_owner_all on public.material_reviews for all using(exists(select 1 from public.material_versions mv join public.materials m on m.id=mv.material_id where mv.id=material_version_id and m.owner_id=auth.uid())) with check(reviewer_id=auth.uid());
create policy classroom_teacher_all on public.classrooms for all using(teacher_id=auth.uid()) with check(teacher_id=auth.uid());
create policy classroom_member_read on public.classrooms for select using(exists(select 1 from public.classroom_members cm where cm.classroom_id=id and cm.student_id=auth.uid()));
create policy membership_read on public.classroom_members for select using(student_id=auth.uid() or exists(select 1 from public.classrooms c where c.id=classroom_id and c.teacher_id=auth.uid()));
create policy assignment_teacher_all on public.assignments for all using(exists(select 1 from public.classrooms c where c.id=classroom_id and c.teacher_id=auth.uid())) with check(created_by=auth.uid() and exists(select 1 from public.classrooms c where c.id=classroom_id and c.teacher_id=auth.uid()));
create policy assignment_student_read on public.assignments for select using(published_at is not null and exists(select 1 from public.classroom_members cm where cm.classroom_id=classroom_id and cm.student_id=auth.uid()));
create policy submissions_student_all on public.submissions for all using(student_id=auth.uid()) with check(student_id=auth.uid());
create policy submissions_teacher_read on public.submissions for select using(exists(select 1 from public.assignments a join public.classrooms c on c.id=a.classroom_id where a.id=assignment_id and c.teacher_id=auth.uid()));
create policy answers_via_submission on public.submission_answers for all using(exists(select 1 from public.submissions s where s.id=submission_id and s.student_id=auth.uid())) with check(exists(select 1 from public.submissions s where s.id=submission_id and s.student_id=auth.uid() and s.status in ('draft','returned')));
create policy claimed_drafts_read on public.external_material_drafts for select using(claimed_by=auth.uid());

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('material-assets','material-assets',false,15728640,array['image/png','image/jpeg','image/webp']),('submission-assets','submission-assets',false,15728640,array['image/png','image/jpeg','image/webp']) on conflict(id) do update set public=false;
create policy material_storage_owner_write on storage.objects for insert to authenticated with check(bucket_id='material-assets' and (storage.foldername(name))[1]=auth.uid()::text);
create policy material_storage_owner_read on storage.objects for select to authenticated using(bucket_id='material-assets' and (storage.foldername(name))[1]=auth.uid()::text);
create policy submission_storage_owner on storage.objects for all to authenticated using(bucket_id='submission-assets' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='submission-assets' and (storage.foldername(name))[1]=auth.uid()::text);
commit;
